head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.dataNum;
scwin.gCheckTF = true;
scwin.gMsgStr;
scwin.gType;
scwin.nmListSeq;
scwin.strCBData;
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gSndloc = js_sndloc; //송신처구분코드
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF35005_POP.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


//수정
scwin.fn_read = function() {
    var url = "/AtsContactInfo.do?method=readAtsEmContactNmList&inputMessageId=INT_ATSCONTACT_INOUT" + "&NMLIST_SEQ=" + scwin.nmListSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_nmListInfo.DataID = encodeURI(url);
    dts_nmListInfo.reset();
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_replace = function(datastr) {
    datastr = datastr.replace(/[-.]/g, "");
    datastr = datastr.replace(/\s/g, "");
    return datastr;
};


//번호중복체크
scwin.fn_checkList = function() {
    var url = "/AtsContactInfo.do?method=checkAtsEmContactNmList" + "&CELLPHONE_NO=" + scwin.fn_replace($c.stf.getObjectValue(tbox_cellphone)) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MktTpCd) + "&SNDLOC_TP_CD=" + $c.stf.getObjectValue(rdo_SndLocTpCd) + "&NMLIST_SEQ=" + $c.stf.getObjectValue(tbox_nmlist_seq) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_checkList.DataID = encodeURI(url);
    dts_checkList.reset();
    var vCntNo = dts_checkList.getCellData(1, "CNTNO");
    if (vCntNo > 0) {
        scwin.gCheckTF = false;
    } else {
        scwin.gCheckTF = true;
    }
};



//저장
scwin.fn_save = function() {
    scwin.fn_checkList();
    if (scwin.gCheckTF == false) {
        $c.win.alert("동일한 휴대폰 번호가 존재합니다.");
        return;
    }
    if (!scwin.checkMaxLength1(tbox_belng_hq, 40, "소속본부")) {
        tbox_belng_hq.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_depnm, 40, "담당부서")) {
        tbox_depnm.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_chrgteam, 40, "담당팀")) {
        tbox_chrgteam.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_jobtitle, 40, "직위")) {
        tbox_jobtitle.focus();
        return;
    }

    //필수
    if ($c.stf.getObjectValue(tbox_empnm) == "") {
        $c.win.alert("담당자명을 확인하여 주십시요");
        tbox_empnm.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_empnm, 40, "담당자명")) {
        tbox_empnm.focus();
        return;
    }
    if ($c.stf.getObjectValue(tbox_telno) == "") {
        $c.win.alert("전화번호를 확인하여 주십시요");
        tbox_telno.focus();
        return;
    }
    if (isNaN(scwin.fn_replace($c.stf.getObjectValue(tbox_telno)))) {
        $c.win.alert("전화번호를 숫자형식으로 값을 입력해주세요.(구분은 '-', '.' 만 사용)");
        tbox_telno.focus();
        return;
    }
    if ($c.stf.getObjectValue(tbox_cellphone) == "") {
        $c.win.alert("핸드폰번호를 확인하여 주십시요");
        tbox_cellphone.focus();
        return;
    }
    if (isNaN(scwin.fn_replace($c.stf.getObjectValue(tbox_cellphone)))) {
        $c.win.alert("핸드폰번호를 숫자형식으로 값을 입력해주세요.(구분은 '-', '.' 만 사용)");
        tbox_cellphone.focus();
        return;
    }
    if ($c.stf.getObjectValue(tbox_cellphone) == "") {
        $c.win.alert("핸드폰번호를 확인하여 주십시요");
        tbox_cellphone.focus();
        return;
    }
    if ($c.stf.getObjectValue(tbox_email) == "") {
        $c.win.alert("E-mail 를 확인하여 주십시요");
        tbox_email.focus();
        return;
    }
    if ("" != tbox_email.getValue()) {
        var a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a == tbox_email.getValue().length - 1) {
            $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.focus();
            return;
        }
    }
    if (!scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.focus();
        return;
    }
    if (scwin.gType == "N") {
        scwin.gMsgStr = "신규등록";
    } else {
        scwin.gMsgStr = "수정";
    }
    var rtn = window.confirm('[' + scwin.gMsgStr + ']하시겠습니까?');
    if (rtn == 1) {
        dts_nmListInfo.setCellData(1, "CONTN_ID", scwin.gType);
        dts_nmListInfo.setCellData(1, "LST_ADJPRN_ID", scwin.gEmpNo);
        trs_Save.Action = "/AtsContactInfo.do?method=registerAtsEmContactNm&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_nmListInfo)";
        trs_Save.Post();
    }
};
scwin.dts_checkList_OnLoadCompleted = function(rowcount) {

};
scwin.dts_checkList_OnLoadError = function() {
    $c.win.alert("핸드폰 중복체크를 할수 없습니다. 시스템 관리자에게 문의하세요");
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "비상연락망 " + scwin.gMsgStr));
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "비상연락망 " + scwin.gMsgStr));
};
scwin.dts_checkList_OnLoadCompleted = function(rowcount) {
    if (dts_checkList.errorMsg) {
        $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
    }
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(tbox_nmlist_seq, false);

    /*if(gLdMktTp == "1" || gLdMktTp == "2"){
    	showObj(rdo_MktTpCd, false);
    	showObj(label_29, false);
    }*/
    $c.stf.showObj(rdo_MktTpCd, false);
    $c.stf.showObj(label_29, false);
    $c.stf.showObj(lbl_9, false);
    $c.stf.showObj(rdo_SndLocTpCd, false);
    $c.stf.setObjectValue(rdo_MktTpCd, '9');
    scwin.gType = $c.frame.path("../").scwin.gType;
    if (scwin.gSndloc == "11" || scwin.gSndloc == "13") {
        if (scwin.gSndloc == "11") {
            rdo_SndLocTpCd.cols = "1";
            rdo_SndLocTpCd.format = "11^공시부";
            rdo_SndLocTpCd.reset();
        } else {
            rdo_SndLocTpCd.cols = "1";
            rdo_SndLocTpCd.format = "13^시장부";
            rdo_SndLocTpCd.reset();
        }
    } else {
        rdo_SndLocTpCd.cols = "2";
        rdo_SndLocTpCd.format = "11^공시부,13^시장부";
    }

    //수정
    if (scwin.gType != "N") {
        scwin.nmListSeq = $c.frame.path("../").inputSeq;
        scwin.fn_read();
    }
    //신규
    else {
        dts_nmListInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INT_ATSCONTACT_INOUT";
        dts_nmListInfo.Reset();
        dts_nmListInfo.insertRow();
        if (scwin.gSndloc == "11" || scwin.gSndloc == "13") {
            $c.stf.setObjectValue(rdo_SndLocTpCd, scwin.gSndloc);
        } else {
            $c.stf.setObjectValue(rdo_SndLocTpCd, "11");
        }
        $c.stf.setObjectValue(rdo_MktTpCd, '9');

        /*if(gLdMktTp == "1" || gLdMktTp == "2"){
        	showObj(rdo_MktTpCd, false);
        	showObj(label_29, false);
        	setObjectValue(rdo_MktTpCd, gLdMktTp);		
        }
        else{
        	setObjectValue(rdo_MktTpCd, '9');		
        }*/

    }
};
